// DOD-9 advisory provider-semantics model, NOT a workflow or acceptance policy.
// Source: https://github.blog/changelog/2026-05-07-github-actions-concurrency-groups-now-allow-larger-queues/
// Models an isolated group in arrival order; not proof of provider ordering, queue fairness, or actual historical cancellations.
// Refuses scenarios beyond 100 pending rather than inventing overflow semantics.
function simulate(events,mode){if(!["default","max","cancel-running"].includes(mode))throw Error("unsupported policy");let active=null,pending=[],completed=[],cancelled=[],seen=new Set();for(const e of events){if(e.type==="arrival"){if(typeof e.id!=="string"||!e.id||seen.has(e.id))throw Error("invalid or duplicate arrival");seen.add(e.id);if(active===null){active=e.id;continue}if(mode==="cancel-running"){cancelled.push(active,...pending);active=e.id;pending=[]}else if(mode==="default"){cancelled.push(...pending);pending=[e.id]}else{if(pending.length>=100)throw Error("outside modeled queue capacity");pending.push(e.id)}}else if(e.type==="complete"){if(e.id!==active||active===null)throw Error("foreign completion");completed.push(active);active=pending.shift()??null}else throw Error("unknown event")}return {active,pending,completed,cancelled}}
function selftest(){const arrivals=["A","B","C"].map(id=>({type:"arrival",id}));const equal=(a,b)=>JSON.stringify(a)===JSON.stringify(b);const checks=[["default pending displacement",simulate(arrivals,"default"),{active:"A",pending:["C"],completed:[],cancelled:["B"]}],["max preserves pending",simulate(arrivals,"max"),{active:"A",pending:["B","C"],completed:[],cancelled:[]}],["PR cancellation intentional",simulate(arrivals,"cancel-running"),{active:"C",pending:[],completed:[],cancelled:["A","B"]}],["drain max",simulate([...arrivals,...["A","B","C"].map(id=>({type:"complete",id}))],"max"),{active:null,pending:[],completed:["A","B","C"],cancelled:[]}],["drain default",simulate([...arrivals,...["A","C"].map(id=>({type:"complete",id}))],"default"),{active:null,pending:[],completed:["A","C"],cancelled:["B"]}]];for(const [name,actual,expected] of checks)if(!equal(actual,expected))throw Error(name);for(const [name,events,mode] of [["foreign completion",[{type:"complete",id:"X"}],"max"],["duplicate arrival",[...arrivals,arrivals[0]],"max"],["over capacity",Array.from({length:102},(_,i)=>({type:"arrival",id:String(i)})),"max"],["invalid policy",arrivals,"invalid"]]){let rejected=false;try{simulate(events,mode)}catch(e){rejected=true}if(!rejected)throw Error(name);checks.push([name])}return checks.map(([name])=>name)}
console.log(JSON.stringify({authority:false,tests:selftest(),scope:'synthetic isolated group only'},null,2));
